// One-off 14 Oct 2026: fill EMPTY cells of the shared glossary only. A non-empty cell is never changed.
const LIMIT = 0; // 1 = test on the first term only; 0 = all terms
const NOTE = 'extracted automatically from text, to be confirmed by linguist';
// [termId, text, translatable(1) / do-not-translate copy(0), [langIds]]
const PLAN = [[7173625,"Vincente",1,[734]],[7173625,"Presteerder",1,[737]],[7173625,"Triunfador",1,[1056]],[7173625,"Pasiekėjas",1,[10152]],[7173650,"App Store",0,[666,708,768,799,10159]],[7173651,"Apple Pay",0,[708]],[7173689,"comando",1,[708]],[7173764,"Facebook",0,[708]],[7173789,"Google Pay",0,[708]],[7173847,"Mobitrace",0,[666,708,761,765,768,773,793,799,818,1056,10152,10153,10154,10159]],[7173857,"Myqrcode.com",0,[666,673,708,733,734,737,744,748,749,753,757,767,768,770,774,799,1056,10159]],[7173858,"MyQRCode.com™",0,[708]],[7173859,"nartsissism",1,[10154]],[7173931,"ScanPRO",0,[666,708,761,765,768,773,793,799,818,1056,10152,10153,10154,10159]],[7176137,"ลืมรหัสผ่านใช่ไหม",1,[753]],[7176137,"¿Olvidaste la contraseña?",1,[1056]],[7176140,"E-Mail-Adresse ist erforderlich",1,[666]],[7176143,"ขอบคุณสำหรับข้อเสนอแนะ!",1,[753]],[7381792,"Réinitialisez votre mot de passe",1,[673]],[7381792,"Wachtwoord opnieuw instellen",1,[737]],[7381793,"Redefinir senha",1,[708]],[7381793,"Wachtwoord opnieuw instellen",1,[737]]];
const a = $('Glossary p1').first().json; const b = $('Glossary p2').first().json || {};
const live = [...(a.data || []), ...(((a.meta || {}).nextCursor) ? (b.data || []) : [])];
if (live.length < 600) throw new Error('Glossary fetch incomplete: ' + live.length + ' terms');
const byId = new Map(live.map(t => [t.id, t]));
const want = new Map();
for (const [id, text, flag, langs] of PLAN) { if (!want.has(id)) want.set(id, []); for (const l of langs) want.get(id).push([l, text, flag]); }
let ids = [...want.keys()]; if (LIMIT) ids = ids.slice(0, LIMIT);
const terms = []; const report = { terms: 0, filled: 0, skipped_not_empty: [], missing_term: [] };
for (const id of ids) {
  const t = byId.get(id); if (!t) { report.missing_term.push(id); continue; }
  const tr = (t.translations || []).map(x => ({ langId: x.langId, translation: x.translation || '', description: x.description || '' }));
  let changed = false;
  for (const [langId, text, flag] of want.get(id)) {
    const cell = tr.find(x => x.langId === langId);
    if (cell && String(cell.translation).trim()) { report.skipped_not_empty.push([t.term, langId, cell.translation]); continue; }
    if (cell) { cell.translation = text; if (flag && !cell.description) cell.description = NOTE; }
    else tr.push({ langId, translation: text, description: flag ? NOTE : '' });
    changed = true; report.filled++;
  }
  if (changed) { terms.push({ id, translations: tr }); report.terms++; }
}
if (!terms.length) throw new Error('Nothing to write: ' + JSON.stringify(report));
return [{ json: { body: { terms }, report } }];
